'use strict';

const fs = require('fs');
const input = fs.readFileSync(0, 'utf8');

let pos = 0;
function nextInt() {
  while (pos < input.length && input.charCodeAt(pos) <= 32) pos++;
  let value = 0;
  while (pos < input.length) {
    const c = input.charCodeAt(pos);
    if (c < 48 || c > 57) break;
    value = value * 10 + c - 48;
    pos++;
  }
  return value;
}

const N = nextInt();
const M = nextInt();
const graph = Array.from({ length: N }, () => []);

for (let i = 0; i < M; i++) {
  const a = nextInt() - 1;
  const b = nextInt() - 1;
  graph[a].push(b);
  graph[b].push(a);
}

const visited = new Uint8Array(N);
const marked = new Uint8Array(N);
const stack = [];
let answer = '-1';

for (let start = 0; start < N; start++) {
  if (visited[start]) continue;

  const component = [];
  visited[start] = 1;
  stack.push(start);

  while (stack.length) {
    const v = stack.pop();
    component.push(v);
    for (const u of graph[v]) {
      if (!visited[u]) {
        visited[u] = 1;
        stack.push(u);
      }
    }
  }

  if (component.length < 3) continue;

  let candidate = -1;
  for (const v of component) {
    if (graph[v].length < component.length - 1) {
      candidate = v;
      break;
    }
  }

  if (candidate !== -1) {
    for (const u of graph[candidate]) marked[u] = 1;
    for (const v of component) {
      if (v !== candidate && !marked[v]) {
        answer = `${candidate + 1} ${v + 1}`;
        break;
      }
    }
    break;
  }
}

